import sys, subprocess, json
sys.path.insert(0, '/tmp/probe/py')
from png import decode_png, px
from collections import Counter

BG = (0,0,0)

def render(code, lang, out, extra=None, cfg='/tmp/probe/cfg_black.json'):
    cmd = ['/workspace/executable','-c',code,'-l',lang,'-o',out,'--silent',
           '--config',cfg,'--scale-factor','1']
    if extra: cmd += extra
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(r.stderr or r.stdout)

def window_bg(buf, w, h):
    c = Counter()
    for y in range(0, h, 3):
        for x in range(0, w, 3):
            p = px(buf,w,x,y)[:3]
            c[p]+=1
    # most common non-black color is window bg
    for col,n in c.most_common(10):
        if col != BG:
            return col
    return None

def analyze(path, lines):
    w,h,buf = decode_png(path)
    winbg = window_bg(buf,w,h)
    # find window rect
    xs=[]; ys=[]
    for y in range(h):
        for x in range(w):
            if px(buf,w,x,y)[:3]==winbg:
                xs.append(x); ys.append(y)
    x0,x1,y0,y1 = min(xs),max(xs),min(ys),max(ys)
    print(f"image {w}x{h}, window bg={winbg} rect=({x0},{y0})-({x1},{y1})")
    # row profile: rows with pixels != winbg inside window
    def rowhas(y):
        for x in range(x0, x1+1):
            p = px(buf,w,x,y)[:3]
            if p != winbg:
                return True
        return False
    bands=[]
    y=y0
    while y<=y1:
        if rowhas(y):
            ystart=y
            while y<=y1 and rowhas(y): y+=1
            bands.append((ystart,y-1))
        else:
            y+=1
    print(f"{len(bands)} text bands: {bands}")
    if len(bands)!=len(lines):
        print("WARNING band count != line count")
    for (ya,yb),src in zip(bands, lines):
        hist=Counter()
        xranges={}
        for y in range(ya,yb+1):
            for x in range(x0,x1+1):
                p=px(buf,w,x,y)[:3]
                if p!=winbg:
                    hist[p]+=1
                    if p in xranges:
                        xranges[p][0]=min(xranges[p][0],x); xranges[p][1]=max(xranges[p][1],x)
                    else:
                        xranges[p]=[x,x]
        # report top colors
        top=hist.most_common(6)
        print(f"  line {src!r:30} band y={ya}-{yb}")
        for col,n in top:
            print(f"    #{col[0]:02x}{col[1]:02x}{col[2]:02x} n={n} x=[{xranges[col][0]},{xranges[col][1]}]")
    return winbg

if __name__=='__main__':
    lang=sys.argv[1]; srcfile=sys.argv[2]; out=sys.argv[3]
    code=open(srcfile).read()
    lines=code.rstrip('\n').split('\n')
    render(code, lang, out)
    analyze(out, lines)
