import sys, subprocess
sys.path.insert(0, '/tmp/probe/py')
from png import decode_png, px
from collections import Counter

BG = (0,0,0)

def render(code, lang, out, extra=None, cfg='/tmp/probe/cfg_black.json'):
    cmd = ['/workspace/executable','-c',code,'-l',lang,'-o',out,'--silent',
           '--config',cfg,'--scale-factor','1']
    if extra: cmd += extra
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError((r.stderr or r.stdout).strip())

def analyze(path, lines, verbose=True):
    w,h,buf = decode_png(path)
    c = Counter()
    for y in range(0,h,3):
        for x in range(0,w,3):
            p = px(buf,w,x,y)[:3]
            if p != BG: c[p]+=1
    winbg = c.most_common(1)[0][0]
    pts=[(x,y) for y in range(h) for x in range(w) if px(buf,w,x,y)[:3]==winbg]
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
    x0,x1,y0,y1=min(xs),max(xs),min(ys),max(ys)
    if verbose: print(f"image {w}x{h}, window bg=#{winbg[0]:02x}{winbg[1]:02x}{winbg[2]:02x} rect=({x0},{y0})-({x1},{y1})")
    ix0, ix1 = x0+4, x1-4   # skip window edge outline
    def rowhas(y):
        for x in range(ix0, ix1+1):
            if px(buf,w,x,y)[:3]!=winbg: return True
        return False
    bands=[]; y=y0
    while y<=y1:
        if rowhas(y):
            ys0=y
            while y<=y1 and rowhas(y): y+=1
            bands.append((ys0,y-1))
        else: y+=1
    if verbose: print(f"{len(bands)} bands vs {len(lines)} lines")
    results=[]
    for (ya,yb),src in zip(bands,lines):
        hist=Counter(); xr={}
        for yy in range(ya,yb+1):
            for x in range(ix0,ix1+1):
                p=px(buf,w,x,yy)[:3]
                if p!=winbg:
                    hist[p]+=1
                    e=xr.get(p)
                    if e: e[0]=min(e[0],x); e[1]=max(e[1],x)
                    else: xr[p]=[x,x]
        entries=[]
        for col,n in hist.most_common(8):
            entries.append((f"#{col[0]:02x}{col[1]:02x}{col[2]:02x}", n, tuple(xr[col])))
        results.append((src,(ya,yb),entries))
        if verbose:
            print(f"  {src!r:34} y={ya}-{yb}: " + "; ".join(f"{c} n={n} x={r}" for c,n,r in entries))
    return winbg, results

if __name__=='__main__':
    lang,srcfile,out = sys.argv[1],sys.argv[2],sys.argv[3]
    code=open(srcfile).read()
    render(code, lang, out)
